'use strict';
// One browser-local classroom shared by teacher controls and student previews.
const classroomKey='whose-side-classroom-v1';
const lessonTopics=['학교 과제에 생성형 AI 사용을 허용해야 할까?','수업 중 학생의 스마트폰 사용을 제한해야 할까?','학교 내 CCTV 설치 범위를 확대해야 할까?','교복 착용을 학생 자율에 맡겨야 할까?','학교 급식의 잔반을 줄이기 위한 규칙을 도입해야 할까?','청소년의 대중교통 요금을 더 지원해야 할까?'];
let classroom;
try{classroom=JSON.parse(localStorage.getItem(classroomKey)||'null');}catch{}
classroom=Object.assign({created:false,name:'2학년 4반 토론 수업',topic:lessonTopics[0],groups:4,size:6,minutes:15,swappers:1,code:'WS2046',joined:0,phase:'대기',paused:false,remaining:900,group:1,device:'laptop',notice:''},classroom||{});
let topicChoice=classroom.topic;
const teacherRoutes=['teacher','teacher-create','teacher-lobby','teacher-live','teacher-report'];
const isTeacher=()=>location.hash.slice(1).startsWith('teacher');
function saveClassroom(){try{localStorage.setItem(classroomKey,JSON.stringify(classroom));}catch{}topic=classroom.topic;window.demoRoomCode=classroom.created?classroom.code:'BR2046';}
saveClassroom();
function tButton(label,action,style=''){return `<button class="button ${style}" data-teacher="${action}">${label}</button>`;}
function teacherGo(route){stopVoice(true);timerRunning=false;location.hash=route;if(location.hash.slice(1)===route)render();window.scrollTo(0,0);}
const originalStudentRender=render;
const oldEntrance=screens.entrance;
screens.entrance=()=>`<div class="portal"><p class="eyebrow">서로 다른 입장에서 시작하는 토론</p><h1>어느 쪽에 서면,<br>무엇이 달라질까요?</h1><p class="portal-sub">역할을 맡아 말하고, 서로의 생각을 이해하는 수업.</p><div class="portal-paths"><article><span class="portal-icon">${icon('users',25)}</span><span class="eyebrow">선생님</span><h2>오늘의 토론을 열어요.</h2><p>주제를 고르고 방을 만든 뒤,<br>모둠의 대화를 한눈에 살펴보세요.</p>${tButton('방 만들기','teacher-create')}<button class="text-button" data-teacher="teacher">선생님 수업 공간 ${icon('arrow',14)}</button></article><article><span class="portal-icon">${icon('chat',25)}</span><span class="eyebrow">학생</span><h2>나와 다른 시선으로.</h2><p>선생님에게 받은 코드로 입장하고,<br>새로운 역할로 생각을 나눠보세요.</p>${button('방 코드로 입장','join-dialog','secondary')}<button class="text-button" data-action="practice">먼저 연습해보기 ${icon('arrow',14)}</button></article></div><p class="fine">6–8명씩 모둠 토론 · 약 15분 · 회원가입 없이</p><p class="demo-disclosure">수정 데모 · 방과 수업 기록은 이 브라우저에서만 연결됩니다. 다른 기기 접속과 음성·AI는 예시 시연입니다.</p></div>`;
$('.view-switch').insertAdjacentHTML('beforeend','<button class="demo-tab teacher-tab" data-teacher="teacher">선생님 화면</button>');
$('.demo-label').textContent='학생·선생님 통합 수정 데모';
function teacherHeading(title,desc){return `<div class="teacher-heading"><div><p class="eyebrow">선생님 수업 공간</p><h1>${title}</h1><p>${desc}</p></div><div class="device-picks" role="group" aria-label="기기 미리보기">${[['laptop','노트북'],['ipad','iPad'],['galaxy','Galaxy Tab']].map(([key,label])=>`<button data-device-preset="${key}" aria-pressed="${classroom.device===key}">${label}</button>`).join('')}</div></div>`;}
function lessonSummary(){return `<article class="teacher-panel lesson-summary"><span class="eyebrow">오늘의 수업</span><h2>${esc(classroom.name)}</h2><p>${esc(classroom.topic)}</p><dl><div><dt>모둠</dt><dd>${classroom.groups}개 · 모둠당 ${classroom.size}명</dd></div><div><dt>토론 시간</dt><dd>${classroom.minutes}분</dd></div><div><dt>역할 전환자</dt><dd>모둠당 ${classroom.swappers}명</dd></div></dl><span class="tag subtle">${esc(classroom.phase)}</span></article>`;}
function teacherHome(){return teacherHeading('서로의 생각이 만나는 수업.','방을 열고, 학생들이 대화할 자리를 준비하세요.')+`<section class="teacher-welcome teacher-panel"><div><span class="portal-icon">${icon('users',30)}</span><h2>오늘은 어떤 이야기를 나눌까요?</h2><p>주제 선택부터 모둠의 회고까지,<br>수업의 흐름을 한곳에서 함께해요.</p>${tButton('새 토론 방 만들기','teacher-create')}</div><ol><li><b>01</b><span>주제를 고르고 방 만들기</span></li><li><b>02</b><span>코드를 공유하고 학생 맞이하기</span></li><li><b>03</b><span>모둠의 토론을 살펴보고 회고하기</span></li></ol></section>${classroom.created?`<div class="teacher-section-title"><h2>이어서 진행할 수업</h2>${tButton('수업 열기',classroom.phase==='대기'?'teacher-lobby':classroom.phase==='종료'?'teacher-report':'teacher-live','secondary')}</div>${lessonSummary()}`:''}`;}
function teacherCreate(){return teacherHeading('오늘 수업의 주제를 골라 주세요.','주제와 모둠 구성을 정하면 학생들이 입장할 방이 만들어져요.')+`<form id="teacher-create-form" class="teacher-create-grid"><section><div class="teacher-section-title"><h2>토론 주제</h2><button type="button" class="text-button" data-teacher="random-topic">무작위로 고르기 ${icon('reset',14)}</button></div><div class="topic-options" role="radiogroup" aria-label="토론 주제">${lessonTopics.map((t,i)=>`<label class="topic-option"><input type="radio" name="lesson-topic" value="${esc(t)}" ${topicChoice===t?'checked':''} required><span class="topic-number">0${i+1}</span><span><strong>${esc(t)}</strong><small>${['배움의 과정과 도구의 사용','학습과 학생의 선택권','안전과 개인정보','자율성과 공동체의 규칙','환경과 서로 다른 식사량','이동권과 공공 예산'][i]}</small></span></label>`).join('')}</div><p class="fine">주제를 바꿔도 이 수정 데모의 역할과 발언은 예시로 표시됩니다.</p></section><aside class="teacher-panel"><h2>수업 설정</h2><label class="field-label" for="lesson-name">수업 이름</label><input class="text-input" id="lesson-name" name="lesson-name" value="${esc(classroom.name)}" maxlength="60" required><div class="teacher-fields"><div><label class="field-label" for="group-count">모둠 수</label><select id="group-count" name="groups">${[1,2,3,4,5,6].map(n=>`<option ${n===classroom.groups?'selected':''}>${n}</option>`).join('')}</select></div><div><label class="field-label" for="group-size">모둠당 인원</label><select id="group-size" name="size">${[6,7,8].map(n=>`<option ${n===classroom.size?'selected':''}>${n}</option>`).join('')}</select></div></div><label class="field-label" for="lesson-time">토론 시간</label><select id="lesson-time" name="minutes">${[10,15,20,25].map(n=>`<option value="${n}" ${n===classroom.minutes?'selected':''}>${n}분</option>`).join('')}</select><fieldset class="teacher-choice"><legend>역할 전환자 수</legend>${[1,2].map(n=>`<label><input type="radio" name="swappers" value="${n}" ${n===classroom.swappers?'checked':''}> ${n}명</label>`).join('')}</fieldset><p class="fine">처음에는 모둠당 1명을 추천해요.</p><button class="button wide" type="submit">${classroom.created?'새 방 만들기':'방 만들기'} ${icon('arrow',16)}</button>${classroom.created?'<p class="fine">새 방을 만들면 이 브라우저의 현재 수업 시연 기록이 바뀝니다.</p>':''}</aside></form>`;}
function groupCards(live=false){return `<div class="teacher-groups">${Array.from({length:classroom.groups},(_,i)=>{const n=Math.min(classroom.size,Math.max(0,classroom.joined-i*classroom.size));return `<button class="group-card ${classroom.group===i+1?'selected':''}" data-group="${i+1}"><span class="group-card-top"><strong>${i+1}모둠</strong><span class="tag subtle">${n===classroom.size?(live?classroom.phase:'준비 완료'):'입장 대기'}</span></span><span class="group-people">${Array.from({length:classroom.size},(_,j)=>`<i class="${j<n?'arrived':''}">${j<n?['유','하','민','서','도','지','수','현'][j]:'·'}</i>`).join('')}</span><span class="group-card-bottom">${n} / ${classroom.size}명${live?'<span>대화 살펴보기 →</span>':'<span>참가자 확인 →</span>'}</span></button>`;}).join('')}</div>`;}
function teacherLobby(){return teacherHeading('학생들을 맞이할 준비가 됐어요.','방 코드를 공유하고, 모둠별 입장을 확인하세요.')+`<div class="teacher-lobby-grid"><section><div class="room-code-panel"><div><span class="eyebrow">학생 입장 코드</span><strong>${classroom.code}</strong><p>${esc(classroom.name)}</p></div><div>${tButton('코드 복사','copy-code','secondary')}${tButton('학생 입장 화면 보기','student-join','secondary')}</div></div><div class="teacher-section-title"><h2>모둠별 입장 <span>${classroom.joined} / ${classroom.groups*classroom.size}명</span></h2><button class="text-button" data-teacher="sample-join">예시 학생 입장시키기</button></div>${groupCards()}<div class="teacher-panel group-detail"><h3>${classroom.group}모둠 참가자</h3><p>${classroom.joined?['유나','하린','민준','서윤','도윤','지우','수빈','현우'].slice(0,Math.min(classroom.size,Math.max(0,classroom.joined-(classroom.group-1)*classroom.size))).join(' · ')||'아직 입장한 학생이 없어요.':'아직 입장한 학생이 없어요.'}</p></div></section><aside>${lessonSummary()}<div class="teacher-panel"><h3>수업을 시작할까요?</h3><p class="fine">학생들은 주제 소개와 규칙을 확인한 뒤 역할을 받아요.</p>${tButton('수업 시작하기','start','wide')}${tButton('설정 다시 보기','teacher-create','secondary wide')}</div></aside></div>`;}
function teacherDock(){return `<div class="teacher-touch-dock"><span>수업 제어</span>${tButton(classroom.paused?'다시 시작':'잠시 멈추기','pause','secondary')}${tButton('＋ 2분','add-time','secondary')}${tButton(classroom.phase==='토론'?'추리로':'마무리',classroom.phase==='토론'?'vote-phase':'finish')}</div>`;}
function teacherLive(){const m=Math.floor(classroom.remaining/60),s=classroom.remaining%60;return teacherHeading('대화의 흐름을 살펴보세요.','말의 정답보다, 모두가 생각을 나누고 있는지 확인해요.')+`<div class="teacher-live-grid"><section><div class="teacher-section-title"><div><h2>${esc(classroom.name)}</h2><p class="teacher-topic">${esc(classroom.topic)}</p></div><span class="tag">${esc(classroom.phase)}</span></div>${groupCards(true)}<article class="teacher-panel observation"><div class="teacher-section-title"><h2>${classroom.group}모둠의 대화</h2><span class="fine">예시 요약</span></div><p class="observation-quote">“AI를 활용하더라도, 스스로 배운 내용을 설명할 수 있어야 해요.”</p><p class="fine">도구의 편리함과 배움의 과정 사이에서 사용 기준을 이야기하고 있어요.</p><h3>발언 참여</h3><div class="participation">${['유나','하린','민준','서윤','도윤','지우'].map((n,i)=>`<div><span>${n}</span><div><i style="width:${[70,91,52,64,38,57][i]}%"></i></div><small>${[3,4,2,3,1,2][i]}회</small></div>`).join('')}</div><p class="teacher-hint">${icon('chat',17)} “아직 이야기하지 않은 친구의 생각도 들어볼까요?”</p>${classroom.notice?`<div class="teacher-notice">공유한 안내 · ${esc(classroom.notice)}</div>`:''}</article></section><aside><div class="teacher-panel teacher-controls"><span class="eyebrow">수업 진행</span><strong id="teacher-clock" class="teacher-clock">${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}</strong><span id="teacher-running">${classroom.paused?'잠시 멈춤':'토론 진행 중'}</span><div class="teacher-fields">${tButton(classroom.paused?'다시 시작':'잠시 멈추기','pause','secondary')}${tButton('2분 더하기','add-time','secondary')}</div><label class="field-label" for="class-notice">모든 모둠에 안내</label><form id="teacher-notice-form"><textarea id="class-notice" class="text-input" maxlength="160" required placeholder="서로의 이유를 한 번 더 물어보세요."></textarea><button class="button secondary wide">안내 공유하기</button></form><div class="teacher-divider"></div>${tButton(classroom.phase==='토론'?'추리 단계로 이동':'회고로 마무리',classroom.phase==='토론'?'vote-phase':'finish','wide')}${tButton('학생 화면 미리보기','student-live','secondary wide')}</div><p class="demo-disclosure">발언 횟수와 요약은 디자인 검토용 예시입니다. 안내·시간·단계 설정은 이 브라우저에서 연결됩니다.</p></aside></div>${teacherDock()}`;}
function teacherReport(){return teacherHeading('어떤 생각이 새롭게 남았나요?','수업의 장면을 돌아보고, 다음 대화를 준비해요.')+`<div class="teacher-stats"><article><span>참여 학생</span><strong>${classroom.joined}<small>명</small></strong></article><article><span>함께한 모둠</span><strong>${classroom.groups}<small>개</small></strong></article><article><span>토론 시간</span><strong>${classroom.minutes}<small>분</small></strong></article></div><div class="teacher-lobby-grid"><section class="teacher-panel"><span class="eyebrow">학생 회고</span><h2>다른 입장을 이해한 순간</h2><blockquote class="observation-quote">${state.reflection?esc(state.reflection):'“AI 사용을 걱정하는 선생님의 입장도, 배울 기회를 지키려는 마음이라는 걸 알게 됐어요.”'}</blockquote><p class="fine">${state.reflection?'이 브라우저의 학생 화면에서 작성한 회고입니다.':'디자인 검토를 위한 예시 회고입니다.'}</p><h3>다음 수업에서 물어볼 것</h3><p>내 역할과 실제 생각은 어떤 점에서 달랐나요?<br>친구의 어떤 말이 내 생각을 바꾸었나요?</p></section><aside>${lessonSummary()}${tButton('수업 기록 내려받기','export','wide')}${tButton('새 수업 준비하기','teacher-create','secondary wide')}</aside></div>`;}
render=function(){const route=location.hash.slice(1);const teach=isTeacher();if(teach){compact=false;$('#shell').classList.remove('mobile-shell');}$('#shell').classList.toggle('teacher-shell',teach);$('#shell').classList.toggle('teacher-tablet',teach&&classroom.device!=='laptop');$('#shell').dataset.device=classroom.device;$('.teacher-tab').classList.toggle('active',teach);if(!teach){originalStudentRender();if(classroom.created&&current==='discussion'){timerRunning=false;const studentTimer=$('.timer-control');if(studentTimer)studentTimer.style.display="none";const timer=$('#timer-time');if(timer)timer.textContent=`${String(Math.floor(classroom.remaining/60)).padStart(2,'0')}:${String(classroom.remaining%60).padStart(2,'0')}`;}if(classroom.notice&&current==='discussion')$('#screen').insertAdjacentHTML('afterbegin',`<div class="teacher-notice">선생님 안내 · ${esc(classroom.notice)}</div>`);}else{const page=teacherRoutes.includes(route)?route:'teacher';const routes=[['teacher','수업 공간'],['teacher-create','방 만들기'],['teacher-lobby','대기실'],['teacher-live','수업 진행'],['teacher-report','수업 회고']];$('#journey-nav').innerHTML=routes.filter(([id])=>classroom.created||!['teacher-lobby','teacher-live','teacher-report'].includes(id)).map(([id,label])=>`<button class="journey-link ${page===id?'active':''}" data-teacher="${id}" ${page===id?'aria-current="page"':''}>${label}</button>`).join('');$('.demo-tab[data-view="experience"]').classList.remove('active');$('#screen').className='screen teacher-screen';$('#scene-number').textContent='';$('#screen').innerHTML=({'teacher':teacherHome,'teacher-create':teacherCreate,'teacher-lobby':teacherLobby,'teacher-live':teacherLive,'teacher-report':teacherReport}[page])()+`<p class="demo-disclosure">whose side? 수정 데모 · 선생님 설정과 학생 미리보기를 이 브라우저에서 함께 확인하세요.</p>`;document.title='whose side? — 선생님';}$('.teacher-tab').setAttribute('aria-pressed',String(teach));if(teach){$('.demo-tab[data-view="experience"]').setAttribute('aria-pressed','false');$('.demo-tab[data-view="rationale"]').setAttribute('aria-pressed','false');}$('.room-label').textContent=classroom.created?classroom.code+' · '+(teach?'선생님':'학생 미리보기'):'수정 데모';};
document.addEventListener('click',async e=>{const b=e.target.closest('[data-teacher],[data-group],[data-device-preset]');if(!b){if(isTeacher()&&e.target.closest('[data-view]')){e.preventDefault();e.stopImmediatePropagation();const requested=e.target.closest('[data-view]').dataset.view;navigate('entrance',true);if(requested==='rationale'){view='rationale';render();}}return;}e.preventDefault();e.stopImmediatePropagation();if(b.dataset.devicePreset){classroom.device=b.dataset.devicePreset;saveClassroom();render();return;}if(b.dataset.group){classroom.group=Number(b.dataset.group);saveClassroom();render();return;}const a=b.dataset.teacher;if(teacherRoutes.includes(a)){teacherGo(a);return;}switch(a){case 'random-topic':topicChoice=lessonTopics[Math.floor(Math.random()*lessonTopics.length)];render();break;case 'copy-code':try{await navigator.clipboard.writeText(classroom.code);toast('방 코드를 복사했어요.');}catch{toast('입장 코드: '+classroom.code);}break;case 'sample-join':classroom.joined=classroom.groups*classroom.size;saveClassroom();render();toast('예시 학생들이 입장했어요.');break;case 'student-join':navigate('entrance');openModal(`<h2 id="modal-title">학생 입장 미리보기</h2><p>선생님이 만든 방의 코드로 학생 경험을 확인하세요.</p><div class="brief-quote">${classroom.code}</div><p>${esc(classroom.topic)}</p>${button('이 방에 학생으로 입장','teacher-student-enter')}`);break;case 'student-live':navigate(classroom.phase==='추리'?'vote':classroom.phase==='종료'?'reflection':'discussion',true);break;case 'start':if(!classroom.joined){toast('먼저 예시 학생을 입장시켜 주세요.');return;}classroom.phase='토론';classroom.paused=false;saveClassroom();teacherGo('teacher-live');break;case 'pause':classroom.paused=!classroom.paused;saveClassroom();render();break;case 'add-time':classroom.remaining+=120;saveClassroom();render();break;case 'vote-phase':classroom.phase='추리';classroom.paused=true;saveClassroom();render();break;case 'finish':classroom.phase='종료';classroom.paused=true;saveClassroom();teacherGo('teacher-report');break;case 'export':{const text=`whose side? · by Bridge\n${classroom.name}\n주제: ${classroom.topic}\n${classroom.groups}모둠 · ${classroom.joined}명 · ${classroom.minutes}분\n학생 회고: ${state.reflection||'아직 작성하지 않았어요.'}\n수정 데모의 브라우저 내 시연 기록입니다.`;const url=URL.createObjectURL(new Blob(['\ufeff'+text],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='whose-side-수업기록.txt';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}}},true);
document.addEventListener('click',e=>{if(e.target.closest('[data-action="teacher-student-enter"]')){closeModal();state.guideStep='video';state.guideCompleted=false;persist();navigate('orientation',true);}},true);
document.addEventListener('submit',e=>{if(e.target.id==='teacher-create-form'){e.preventDefault();e.stopImmediatePropagation();const f=new FormData(e.target);Object.assign(classroom,{created:true,name:String(f.get('lesson-name')).trim(),topic:String(f.get('lesson-topic')),groups:Number(f.get('groups')),size:Number(f.get('size')),minutes:Number(f.get('minutes')),swappers:Number(f.get('swappers')),joined:0,remaining:Number(f.get('minutes'))*60,phase:'대기',paused:true,notice:'',group:1});classroom.code='WS2046';classroom.practiceMode=false;topicChoice=classroom.topic;saveClassroom();teacherGo('teacher-lobby');toast('시연용 방을 만들었어요.');}if(e.target.id==='teacher-notice-form'){e.preventDefault();e.stopImmediatePropagation();classroom.notice=$('#class-notice').value.trim();saveClassroom();render();toast('학생 미리보기에도 안내를 표시했어요.');}},true);
window.addEventListener('hashchange',()=>{render();});
setInterval(()=>{if(!classroom.created||classroom.paused||classroom.phase!=='토론'||classroom.remaining<=0)return;classroom.remaining--;saveClassroom();const clock=$('#teacher-clock')||$('#timer-time');if(clock)clock.textContent=`${String(Math.floor(classroom.remaining/60)).padStart(2,'0')}:${String(classroom.remaining%60).padStart(2,'0')}`;if(!classroom.remaining){classroom.paused=true;toast('토론 시간이 끝났어요. 추리 단계로 이동해 주세요.');}},1000);
render();

document.addEventListener('click',e=>{if(e.target.closest('#reset-demo')){Object.assign(classroom,{created:false,joined:0,phase:'대기',paused:true,remaining:900,notice:'',topic:lessonTopics[0]});saveClassroom();}},true);

const studentJoinDialog=joinDialog;joinDialog=function(){studentJoinDialog();const code=window.demoRoomCode||'BR2046';$('#room-code').value=code;$('label[for="room-code"] small').textContent='시연 코드 · '+code;};
